package com.digitalhealth.security;
import com.digitalhealth.model.*; import com.digitalhealth.repository.*; import org.springframework.http.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.time.*;
@Service public class AccessService { private final ConsentRepository consents; public AccessService(ConsentRepository c){consents=c;} public AuthenticatedUser current(){Object p=SecurityContextHolder.getContext().getAuthentication()==null?null:SecurityContextHolder.getContext().getAuthentication().getPrincipal();if(p instanceof AuthenticatedUser u)return u;throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Authentication required");} public void workerOrAdmin(Long workerId){var u=current();if(u.role()!=Role.ADMIN&&(u.role()!=Role.WORKER||!workerId.equals(u.workerId())))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You cannot access this worker record");} public void clinicalAccess(Long workerId){var u=current();if(u.role()==Role.ADMIN)return;if(u.role()==Role.WORKER&&workerId.equals(u.workerId()))return;if((u.role()==Role.DOCTOR||u.role()==Role.HEALTHCARE_PROVIDER)&&consents.findByWorkerIdOrderByGrantedDateDesc(workerId).stream().anyMatch(c->c.getStatus().equals("ACTIVE")&&c.getProvider().equalsIgnoreCase(u.username())&&(c.getExpiryDate()==null||!c.getExpiryDate().isBefore(LocalDate.now()))))return;throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Active worker consent is required");} public void providerOrAdmin(){var r=current().role();if(r!=Role.ADMIN&&r!=Role.DOCTOR&&r!=Role.HEALTHCARE_PROVIDER)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Healthcare provider access required");} public void admin(){if(current().role()!=Role.ADMIN)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Administrator access required");} }
